pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PhiNFT1155} from "../src/PhiNFT1155.sol";

contract InvMutTest is Test {
    PhiNFT1155 c;
    function setUp() public { c = new PhiNFT1155(); }
    function testRegression_property() public {
        address newOwner = address(0x1234);

        vm.deal(newOwner, 1 ether);



        uint256 referenceBalance = c.balanceOf(newOwner, 1);
        assertTrue(referenceBalance == 0, "balanceOf should be 0 for uninitialized contract");
